        [Tooltip("Light pillar over a broken friend that answered (WarmLamp, additive, rising bands).")]
        [SerializeField] private Material _friendPillar;

        [Tooltip("The Rover Bay's weld sparks (WarmLamp, additive, soft round sprites).")]
        [SerializeField] private Material _spark;

        [Tooltip("The soft amber halo over home seen from across the basin (WarmLamp, additive, round sprite).")]
        [SerializeField] private Material _homeHalo;

        [Tooltip("The pulse running along the ground from a newly lit relay mast toward home (WarmLamp, additive).")]
        [SerializeField] private Material _linkPulse;

        [Tooltip("The feel kit's glowing sprites: charge motes, the glow bead, flashes, vacuum sparks and slag beads " +
                 "(SoftGlow, white, additive, soft round; each sprite carries its own colour).")]
        [SerializeField] private Material _feelSprite;

        [Tooltip("The cutting beam's hot white core (SoftGlow, additive, soft across).")]
        [SerializeField] private Material _beamCore;

        [Tooltip("The cutting beam's cyan sheath round the core (SoftGlow, additive, soft across, faint bands).")]
        [SerializeField] private Material _beamSheath;

        [Tooltip("The molten seam on a piece, emission by heat (HeatSeam shader).")]
        [SerializeField] private Material _heatSeam;

        [Tooltip("Every look number of the feel kit (Data/Tuning/Gameplay/FeelVfxTuning.asset).")]
        [SerializeField] private FeelVfxTuning _feelTuning;

        [Tooltip("Art's station pads (Generated/Art/Base/StationPad_<cm>), one per size.")]
        [SerializeField] private GameObject[] _pads = Array.Empty<GameObject>();

        [Tooltip("Each pad's radius in metres (Art's PadRadii), matching the pads above.")]
        [SerializeField] private float[] _padRadii = Array.Empty<float>();

        [Tooltip("Art's tower components (Generated/Art/Pickups/Part_*), each named as the part's id.")]
        [SerializeField] private GameObject[] _components = Array.Empty<GameObject>();

        [Tooltip("Art's sealed containers (Generated/Art/Props: CoilCrate, TapeCase, JunctionBox, SupplyPod, " +
                 "TillySled), each named as its prefab (0.5.5 §2).")]
        [SerializeField] private GameObject[] _containers = Array.Empty<GameObject>();

        [Tooltip("Art's scan fragments (Generated/Art/Fragments/Fragment_<Blueprint>_<n>), each named as its prefab " +
                 "(0.5.5 §1).")]
        [SerializeField] private GameObject[] _fragments = Array.Empty<GameObject>();

        [Tooltip("Art's crashed test jumper (Generated/Art/Props/JumperWreck.prefab), holding the Hover-Jump " +
                 "fragments at the chasm's near lip (0.5.5 §1.3).")]
        [SerializeField] private GameObject _jumperWreck;

        [Tooltip("Art's garage service port (Generated/Art/Sites/GaragePort.prefab), with its Tray node " +
                 "(first-hour v2 §3).")]
        [SerializeField] private GameObject _garagePort;

        [Tooltip("Art's tape deck (Generated/Art/Rover/Kit_TapeDeck.prefab, the piece 07 wears), sealed in Kenji's " +
